      "id": 2,
      "claim": "Uninsured individuals must pay the full price of a CT scan out‑of‑pocket.",
      "evidence": "By definition, uninsured patients have no third‑party payer and are billed the provider’s charge in full.",
      "weight": 0.13,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Insured individuals usually have most of the CT cost covered by their health plan.",
      "evidence": "Private and public insurance plans include diagnostic imaging benefits, leaving patients only a copay or deductible that is far lower than the full charge.",
      "weight": 0.13,
      "depends_on": [1]
