      "id": 4,
      "claim": "Higher out‑of‑pocket costs are a strong deterrent to accepting non‑emergency medical procedures.",
      "evidence": "The RAND Health Insurance Experiment and subsequent health‑economics studies found that cost‑sharing reduces utilization of services—including imaging—by 20‑30% when patients face higher out‑of‑pocket payments.",
      "weight": 0.22,
      "depends_on": [2, 3]
    },
    {
      "id": 5,
      "claim": "Empirical studies find that uninsured patients have lower odds of receiving CT scans than insured patients, even after adjusting for clinical need.",
      "evidence": "Analyses of the CDC National Inpatient Sample, JAMA 2009 trauma study, and other hospital discharge databases report that uninsured adults receive 20‑30% fewer diagnostic imaging studies, including CT, than comparable insured adults.",
      "weight": 0.30,
      "depends_on": [4]
    }
